assert parse_all(["1", "2"]) == [1, 2], "parse_all should return the ints when everything parses"
try:
    parse_all(["1", "a", "3", "b"])
except ExceptionGroup as _eg:
    assert _eg.message == "bad items", "the group's message should be 'bad items'"
    assert [str(_e) for _e in _eg.exceptions] == ["bad item: 'a'", "bad item: 'b'"], "one error per bad item, in order"
    assert all(isinstance(_e, ValueError) for _e in _eg.exceptions)
else:
    raise AssertionError("parse_all should raise an ExceptionGroup when items fail to parse")

uth_example:
checks = [("age", "x"), ("score", "-3"), ("rank", "2"), ("level", "")]
problems = []
for name, raw in checks:
    try:
        value = int(raw)
        if value < 0:
            raise ValueError(f"{name} must not be negative")
    except ValueError as exc:
        problems.append(exc)

if problems:
    group = ExceptionGroup("input problems", problems)
    print(group)
    first, rest = group.split(lambda e: "negative" in str(e))
    print("negative:", [str(e) for e in first.exceptions])
    print("other:", len(rest.exceptions))
